import {config} from './config.js';
import {questions,locations,priorities,usefulness,version,validateResponse} from './poll-schema.js';
const root=document.querySelector('#poll-root');
const escape=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let step=0,available=false,preview=false,submitted=false,busy=false;
const answers={version,current:[],placement:'',concerns:[],priorities:[],usefulness:'',improvement:'',currentOther:'',placementOther:'',concernsOther:'',contactName:'',contactEmail:'',contactConsent:false};
let marker;
try{marker=localStorage.getItem(version+'-device');}catch{}
if(!marker){marker=crypto.randomUUID();try{localStorage.setItem(version+'-device',marker);}catch{}}
const tokenHeaders=()=>({'X-Poll-Device':marker});
async function api(path,options={}){const r=await fetch(path,{...options,headers:{...tokenHeaders(),...options.headers},signal:AbortSignal.timeout(12000)});let data;try{data=await r.json();}catch{throw new Error('The poll is not available right now. Please try again later.');}if(!r.ok){const error=new Error(data.error||'Unable to save your response. Please try again.');error.status=r.status;throw error;}return data;}
function focusQuestion(){root.querySelector('legend,h3')?.focus({preventScroll:true});}
function render(){
 const q=questions[step];
 const status=!available?'<p class="notice">The poll is not accepting responses yet. You can look through the questions; nothing will be submitted.</p>':preview?'<p class="notice">Local review mode. Responses stay in a separate test database and are not campaign results.</p>':'';
 root.innerHTML=status+`<div class="poll-top"><span>${q?`QUESTION ${step+1} OF 6`:'OPTIONAL FOLLOW-UP'}</span><span>${q?'ABOUT 1 MINUTE':'NO CONTACT REQUIRED'}</span></div><div class="progress" role="progressbar" aria-label="Poll progress" aria-valuemin="0" aria-valuemax="7" aria-valuenow="${step}"><div style="width:${step/7*100}%"></div></div><form novalidate><fieldset><legend tabindex="-1">${q?escape(q.title):'Would you like to hear from ECS?'}</legend><p class="hint">${q?escape(q.hint):'Your research response can be submitted without your name or email. Contact information stays private.'}</p>${q?q.type==='text'?`<label class="field-label" for="improvement">Your feedback (optional)</label><textarea id="improvement" name="improvement" maxlength="1500">${escape(answers.improvement)}</textarea><p class="hint">1,500 characters maximum</p>`:`<div class="choices">${Object.entries(q.options).map(([value,label])=>`<label class="choice"><input type="${q.type}" name="${q.key}" value="${value}" ${(Array.isArray(answers[q.key])?answers[q.key].includes(value):answers[q.key]===value)?'checked':''}><span>${escape(label)}</span></label>`).join('')}</div>${Object.hasOwn(q.options,'other')?`<div id="other-field" ${([].concat(answers[q.key]).includes('other'))?'':'hidden'}><label class="field-label" for="other">Other — please describe (optional)</label><input id="other" name="${q.key}Other" type="text" maxlength="250" value="${escape(answers[q.key+'Other']||'')}"></div>`:''}`:`<label class="field-label" for="contact-name">Name (optional)</label><input id="contact-name" name="contactName" type="text" autocomplete="name" maxlength="100" value="${escape(answers.contactName)}"><label class="field-label" for="contact-email">Email (optional)</label><input id="contact-email" name="contactEmail" type="email" autocomplete="email" maxlength="254" value="${escape(answers.contactEmail)}"><label class="choice" style="margin-top:18px"><input type="checkbox" name="contactConsent" ${answers.contactConsent?'checked':''}><span>ECS may contact me about my feedback and agricultural product research.</span></label><p class="hint" style="margin-top:18px">ECS stores research answers and any optional contact details. Written answers are for ECS review only. Please submit once per person. A browser marker helps deter duplicates; it does not verify identity.</p><p class="hint">For questions about your response, contact <a href="mailto:${escape(config.contactEmail)}">ECS</a>.</p>`}</fieldset><div class="honeypot" aria-hidden="true"><label>Website<input name="website" type="text" tabindex="-1" autocomplete="off"></label></div><p id="poll-error" class="error" role="alert"></p><div class="poll-actions"><button type="button" class="back" ${step===0?'hidden':''}>Back</button><button class="button primary" type="submit" ${!q&&!available?'disabled':''}>${q?step===5?'Continue':'Next question':'Submit my response'} <span aria-hidden="true">→</span></button></div></form>`;
 const form=root.querySelector('form');
 form.addEventListener('change',()=>{save();const o=root.querySelector('#other-field');if(o)o.hidden=![].concat(answers[q.key]).includes('other');});
 root.querySelector('.back').addEventListener('click',()=>{save();step--;render();focusQuestion();});
 form.addEventListener('submit',async e=>{e.preventDefault();save();if(q){const value=answers[q.key];if(q.type!=='text'&&(!value.length||(q.max&&value.length>q.max))){showError(q.max?`Choose between one and ${q.max} answers.`:'Please choose an answer.');return;}if(q.key==='current'&&value.includes('none')&&value.length>1){showError('Choose a location or “No designated place,” not both.');return;}if(q.key==='concerns'&&value.includes('unsure')&&value.length>1){showError('Choose your concerns or “Not sure,” not both.');return;}step++;render();focusQuestion();}else await submit(form);});
}
function save(){const f=root.querySelector('form');if(!f)return;const d=new FormData(f),q=questions[step];if(q){answers[q.key]=q.type==='checkbox'?d.getAll(q.key):d.get(q.key)||'';if(d.has(q.key+'Other'))answers[q.key+'Other']=d.get(q.key+'Other');}else{answers.contactName=d.get('contactName')||'';answers.contactEmail=d.get('contactEmail')||'';answers.contactConsent=d.has('contactConsent');}}
function showError(text){root.querySelector('#poll-error').textContent=text;}
async function submit(form){if(busy||!available)return;let body;try{body=validateResponse(answers);}catch(e){showError(e.message);return;}busy=true;const b=form.querySelector('[type=submit]');b.disabled=true;b.textContent='Saving your response…';try{await api('/api/poll',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({...body,website:new FormData(form).get('website')||''})});submitted=true;renderThanks();}catch(e){if(e.status===409){submitted=true;renderThanks(true);}else{showError(e.message);b.disabled=false;b.textContent='Try submitting again';}}finally{busy=false;}}
function renderThanks(duplicate=false){root.innerHTML=`<p class="eyebrow">${preview?'LOCAL REVIEW RESPONSE':'FARMER INPUT'}</p><h3 tabindex="-1">${duplicate?'A response is already recorded for this browser.':'Thank you for sharing your experience.'}</h3><p>${duplicate?'To help keep the poll useful, please submit only once per person.':'Your feedback will help ECS understand what belongs in the agricultural readiness conversation.'}</p><button class="button" id="view-results">See aggregate results</button><div id="results" aria-live="polite"></div>`;root.querySelector('#view-results').addEventListener('click',loadResults);focusQuestion();}
async function loadResults(){const target=root.querySelector('#results');target.textContent='Loading results…';try{const d=await api('/api/results');target.innerHTML=`<p class="hint" style="margin-top:24px">${d.total} ${preview?'local test':'submitted'} response${d.total===1?'':'s'}. ${d.total===0?'No results yet.':''} Self-selected responses; not representative of all farmers.</p>`+[[locations,'placement','Where would farmers keep it?'],[priorities,'priorities','What matters most?'],[usefulness,'usefulness','Would GO be useful?']].map(([labels,key,title])=>`<div class="results-group"><h4>${title}</h4>${Object.entries(labels).map(([value,label])=>{const count=d[key][value]||0,percent=d.total?Math.round(count/d.total*100):0;return `<div class="result-label"><span>${escape(label)}</span><span>${count} · ${percent}%</span></div><div class="result-track"><span style="width:${percent}%"></span></div>`;}).join('')}${key==='priorities'?'<p class="hint">Up to three choices per participant; percentages may exceed 100%.</p>':''}</div>`).join('');}catch(e){target.textContent=e.message;}}
document.querySelectorAll('[data-location]').forEach(a=>a.addEventListener('click',()=>{if(submitted)return;save();answers.placement=a.dataset.location;step=0;render();}));
if(config.purchaseUrl){try{const u=new URL(config.purchaseUrl);if(u.protocol==='https:'){document.querySelector('#purchase-action').innerHTML=`<a class="button" href="${escape(u.href)}">Shop at Eagle Corps Essentials <span aria-hidden="true">↗</span></a><p class="small">Continue to the existing store to choose your configuration and check out.</p>`;}}catch{}}
document.querySelector('#contact').innerHTML=`<a href="mailto:${escape(config.contactEmail)}">${escape(config.contactEmail)}</a> · <a href="tel:${escape(config.contactPhone)}">${escape(config.contactPhoneDisplay)}</a>`;
render();
try{const status=await api('/api/status');available=status.accepting;preview=status.preview;submitted=status.submitted;if(submitted)renderThanks(true);else render();}catch{render();}
if(document.modelContext?.registerTool){const lifecycle=new AbortController();window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});try{Promise.resolve(document.modelContext.registerTool({name:'start_farm_readiness_poll',title:'Open the farm readiness poll',description:'Navigate to the poll. Does not submit a response or change answers.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:false},execute:input=>{if(!input||typeof input!=='object'||Object.keys(input).length)throw new Error('This tool accepts an empty object.');document.querySelector('#poll').scrollIntoView();focusQuestion();return {accepting:available,submitted,question:step+1};}},{signal:lifecycle.signal})).catch(()=>{});}catch{}}
